{
  "root": "main_stack",
  "state": {
    "salesData": [
      { "month": "Jan", "sales": 100 },
      { "month": "Feb", "sales": 120 },
      { "month": "Mar", "sales": 90 }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md" },
      "children": [
        "header_stack",
        "intro_text",
        "recommended_chart_title",
        "data_context_text",
        "line_chart_card",
        "sales_data_card",
        "alternative_chart_card",
        "quick_actions_title",
        "actions_stack"
      ]
    },
    "header_stack": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "sm", "align": "center" },
      "children": ["icon_graph_up", "main_title"]
    },
    "icon_graph_up": {
      "type": "Icon",
      "props": { "name": "../assets/r_000805_01_1_graph-up.svg" },
      "children": []
    },
    "main_title": {
      "type": "Text",
      "props": { "text": "Monthly Sales Data Visualization", "variant": "h2" },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "To effectively visualize the provided monthly sales data, which tracks sales figures over a continuous period, a Line Chart is the most suitable option."
      },
      "children": []
    },
    "recommended_chart_title": {
      "type": "Text",
      "props": { "text": "Recommended Chart Type for Sales Trends", "variant": "h3" },
      "children": []
    },
    "data_context_text": {
      "type": "Text",
      "props": {
        "text": "The provided sales data represents a time series, making a line chart ideal for observing trends and changes over time."
      },
      "children": []
    },
    "line_chart_card": {
      "type": "Card",
      "props": {},
      "children": ["line_chart_stack"]
    },
    "line_chart_stack": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": [
        "line_chart_heading",
        "line_chart_purpose",
        "line_chart_xaxis",
        "line_chart_yaxis",
        "line_chart_benefit"
      ]
    },
    "line_chart_heading": {
      "type": "Text",
      "props": { "text": "Line Chart", "variant": "h3" },
      "children": []
    },
    "line_chart_purpose": {
      "type": "Text",
      "props": {
        "text": "Purpose: Excellent for showing trends, patterns, and fluctuations in data over a continuous period. It clearly illustrates how sales evolve from one month to the next."
      },
      "children": []
    },
    "line_chart_xaxis": {
      "type": "Text",
      "props": { "text": "X-axis: Months (January, February, March)" },
      "children": []
    },
    "line_chart_yaxis": {
      "type": "Text",
      "props": { "text": "Y-axis: Sales (100, 120, 90)" },
      "children": []
    },
    "line_chart_benefit": {
      "type": "Text",
      "props": {
        "text": "Benefit: Easily highlights increases or decreases in sales, allowing for quick identification of growth or decline periods."
      },
      "children": []
    },
    "sales_data_card": {
      "type": "Card",
      "props": {},
      "children": ["sales_data_title", "sales_data_table"]
    },
    "sales_data_title": {
      "type": "Text",
      "props": { "text": "Monthly Sales Trend", "variant": "h3" },
      "children": []
    },
    "sales_data_table": {
      "type": "Table",
      "props": {
        "statePath": "/salesData",
        "columns": [
          { "key": "month", "label": "Month" },
          { "key": "sales", "label": "Sales" }
        ],
        "domain": "status",
        "preferredPresentation": "table",
        "primaryColumn": "month",
        "highlightColumns": ["sales"],
        "numericColumns": ["sales"]
      },
      "children": []
    },
    "alternative_chart_card": {
      "type": "Card",
      "props": {},
      "children": ["alt_chart_stack"]
    },
    "alt_chart_stack": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["alternative_chart_heading", "alternative_chart_description"]
    },
    "alternative_chart_heading": {
      "type": "Text",
      "props": { "text": "Alternative (Bar Chart)", "variant": "h3" },
      "children": []
    },
    "alternative_chart_description": {
      "type": "Text",
      "props": {
        "text": "While a line chart emphasizes continuity and trends, a bar chart could also be used to compare individual monthly sales figures. However, for showing a trend over time, a line chart is generally preferred as it visually connects the data points, implying progression."
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": { "text": "Quick Actions", "variant": "h3" },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["button_charting_software", "button_data_viz_guide"]
    },
    "button_charting_software": {
      "type": "Button",
      "props": { "label": "Charting Software" },
      "on": {
        "press": {
          "action": "openUrl",
          "params": { "url": "https://www.tableau.com/products/public" }
        }
      },
      "children": []
    },
    "button_data_viz_guide": {
      "type": "Button",
      "props": { "label": "Data Viz Guide" },
      "on": {
        "press": {
          "action": "openUrl",
          "params": { "url": "https://www.datawrapper.de/blog/data-visualization-guide/" }
        }
      },
      "children": []
    }
  }
}
